async function receivePurchaseOrder(id:string){if(!canEdit('purchaseOrders')||!canEdit('batches')){toast.error('Your role cannot receive purchase orders into stock.');return}const next=structuredClone(s),po=next.purchaseOrders.find(p=>p.id===id);if(!po)return;if(!['Sent','Part received'].includes(po.status)){toast.error('Mark the purchase order sent before receiving stock.');return}let received=0;for(const item of po.items){const outstanding=item.qty-item.receivedQty;if(outstanding<=0)continue;const product=next.products.find(p=>p.id===item.productId);if(!product)continue;next.batches.push({id:uid(),productId:item.productId,qty:outstanding,unitCost:item.unitCost,expiry:shiftDate(365),received:today(),supplierId:po.supplierId,invoice:po.number,dueDate:shiftDate(30),payments:[],paid:false});item.receivedQty+=outstanding;received+=outstanding}if(!received){toast.error('Nothing remains to receive on this PO.');return}po.status=po.items.every(i=>i.receivedQty>=i.qty)?'Received':'Part received';if(await save(next))toast.success(received+' units received into inventory. Review expiry dates on the new batches.')}
